if ~exist('src400sym','var')
    src400sym = sqw('e:\SHARE\Fe\Data\sqw\sqw2024\Fe_ei401_align_sym3.sqw');
end
hc = hor_config;
ll = hc.log_level;
hc.log_level = -2;

w2_000a = cut(src400sym,line_proj('offset',[0,0,1]),[-0.1,0.1],0.04,0.04,[95,105]);
plot(w2_000a);lz 0 1;keep_figure; %[output:2d3e8ddc]
w2_000b = cut(src400sym,line_proj('offset',[0,0,1]),[-0.1,0.1],0.04,0.04,[45,55]);
plot(w2_000b);lz 0 1; keep_figure; %[output:2502f792]


data_path = 'e:\SHARE\Fe\Data\analysis\06_fit_with_J0\sym4D_cutsAndFits' %[output:8e9da991]
fit_cuts_file = 'multicuts_fit_dataGP_ei400meV.mat' %[output:180f73de]
cutsGP400meV_res_file = fullfile(data_path,fit_cuts_file);
if ~exist('cuts2fit400GP','var')
    cuts2fit400GP = recover_cuts_2fit(cutsGP400meV_res_file,'cuts2fit400GP');
end

hc.log_level = ll;

othrEi400cut111 = {[-0.1,0.1],[-0.1,0.1],[0,2,250]};
file = src400sym.full_filename %[output:21a0a3e4]
[~,fname] = fileparts(file);
%%
hc.log_level = -2;

w2_001 = cut(src400sym,line_proj('offset',[0,0,1]),0.04,0.04,[-0.1,0.1],[95,105]);
plot(w2_001);lz 0 1; keep_figure; %[output:8319b665]

w2_00 = cut(src400sym,line_proj(),0.04,0.04,[-0.1,0.1],[95,105]);
[fbase,axbase]=plot(w2_00);lz 0 1;  %[output:3d6aea10]
keep_figure; %[output:3d6aea10]

hc.log_level = ll;

%%
% GP offset <110>; 
hc.log_level = -2;
liny %[output:22255f27]

lp111m = line_proj([-1,1,1],[-1,-1,0],'offset',[1,1,0]);
w2_400off110m = cut(src400sym,lp111m,[0,0.01,1],othrEi400cut111{:});
w2_400off110m.full_filename = [fname,', w2_400off110'];
fh= plot(w2_400off110m); lz 0 1; %[output:34ec5d5d]
[w2_400off110mf,cuts2fit400GP] = draw_masks_helper(fh,cuts2fit400GP,'msk110_dir_m111',1);
plot(w2_400off110mf); lz 0 1;keep_figure %[output:34ec5d5d]
%
lp111p = line_proj([1,-1,1],[1,1,0],'offset',[1,1,0]);
w2_400off110p = cut(src400sym,lp111p,[0,0.01,1],othrEi400cut111{:});
w2_400off110p.full_filename = [fname,', w2_400off110p'];
fh = plot(w2_400off110p); lz 0 1; %[output:36712e5a]
[w2_400off110pf,cuts2fit400GP] = draw_masks_helper(fh,cuts2fit400GP,'msk110_dir_p111',1);
plot(w2_400off110pf); lz 0 1;keep_figure; %[output:36712e5a]

%
w2e400GPoff110 = sqw_op_bin_pixels({w2_400off110m,w2_400off110p}, ...
    @move_all_to_proj, ...
    {[lp111m,lp111p]}, ...
    lp111m,[0,0.01,1],othrEi400cut111{:},'-combine');
plot(w2e400GPoff110);liny; lz 0 1;keep_figure; %[output:074d41db]

w2e400GPoff110f = sqw_op_bin_pixels({w2_400off110mf,w2_400off110pf}, ...
    @move_all_to_proj, ...
    {[lp111m,lp111p]}, ...
    lp111m,[0,0.01,0.35],othrEi400cut111{:},'-combine');
plot(w2e400GPoff110f);liny; lz 0 1;keep_figure;


cuts2fit400GP.cuts_off110 = w2e400GPoff110;
cuts2fit400GP.cuts_off110f = w2e400GPoff110f;
hc.log_level = ll;
%%
scuts_path = 'e:\SHARE\Fe\Data\analysis\07_fit_with_multicut_allJ\sel_cuts';
allJfitfile = fullfile(scuts_path,'J0_3fitOff110Cuts');
if ~exist('multij_110','var')
    multij_110= [];
end
multij_110 = save_selected_cuts(multij_110,allJfitfile,'Ei400_off110GP',cut(w2e400GPoff110f,[],[80,2,160]));
%%
% GP offset <200>; 
hc.log_level = -2;
liny %[output:25fa155a]

lp111m2 = line_proj([-1,1,1],[-1,-1,0],'offset',[2,0,0]);
w2_400off200m = cut(src400sym,lp111m2,[0,0.01,1],othrEi400cut111{:});
w2_400off200m.full_filename = [fname,', w2_400off200m'];
fh= plot(w2_400off200m); lz 0 4; %[output:8473b94f]
[w2_400off200mf,cuts2fit400GP] = draw_masks_helper(fh,cuts2fit400GP,'msk200_dir_m111',1);
plot(w2_400off200mf); lz 0 1;keep_figure %[output:8473b94f]
%
lp111p2 = line_proj([1,-1,1],[1,1,0],'offset',[0,2,0]);
w2_400off200p = cut(src400sym,lp111p2,[0,0.01,1.5],othrEi400cut111{:});
w2_400off200p.full_filename = [fname,', w2_400off200p'];
fh = plot(w2_400off200p); lz 0 4; %[output:7e557004]
[w2_400off200pf,cuts2fit400GP] = draw_masks_helper(fh,cuts2fit400GP,'msk200_dir_p111',1);
plot(w2_400off200pf); lz 0 1;keep_figure; %[output:7e557004]

w2e400GPoff200 = sqw_op_bin_pixels({w2_400off200m,w2_400off200p}, ...
    @move_all_to_proj, ...
    {[lp111m2,lp111p2]}, ...
    lp111m2,[0,0.01,1],othrEi400cut111{:},'-combine');
plot(w2e400GPoff200);liny; lz 0 1;keep_figure; %[output:6f2f7b8d]

w2e400GPoff200f = sqw_op_bin_pixels({w2_400off200mf,w2_400off200pf}, ...
    @move_all_to_proj, ...
    {[lp111m2,lp111p2]}, ...
    lp111m2,[0,0.01,0.35],othrEi400cut111{:},'-combine');
plot(w2e400GPoff200f);liny; lz 0 1;keep_figure; %[output:88c39c68]


cuts2fit400GP.cuts_off200 = w2e400GPoff200;
cuts2fit400GP.cuts_off200f = w2e400GPoff200f;
hc.log_level = ll;
%%
save(cutsGP400meV_res_file,'cuts2fit400GP','-v7.3');

%%
scuts_path = 'e:\SHARE\Fe\Data\analysis\07_fit_with_multicut_allJ\sel_cuts';
allJfitfile = fullfile(scuts_path,'J0_3fitOff110Cuts');
if ~exist('multij_110','var')
    multij_110 = [];
end
multij_110 = save_selected_cuts(multij_110,allJfitfile,'Ei400_off110GP',cut(w2e400GPoff110f,[],[80,2,220]));

%%
hc.log_level = -2;

bg_400o11 = cut(src400sym,line_proj([-1,1,1],[-1,-1,0],'offset',[3,3,0]),[-1,1],othrEi400cut111{:});
%plot(bg_400o11);lz 0 0.5; keep_figure;
acolor k;
plot(bg_400o11); logy; %[output:5a156e01]
bg_400o02 = cut(src400sym,line_proj([1,1,1],[-1,1,0],'offset',[2,4,0]),[-1,1],othrEi400cut111{:});
%
%plot(bg_400o02);lz 0 0.5; keep_figure;
acolor g;
pd(bg_400o02); %[output:5a156e01]

hc.log_level = ll;
%%
hc.log_level = -2;
w111_cuts = repmat(sqw,1,2);

w111_cuts(1) = w2e400GPoff110 - replicate(bg_400o11,w2e400GPoff110); plot(w111_cuts(1)); liny; lz 0 0.5;keep_figure; w111_cuts(1)  = cut(w111_cuts(1) ,[0,0.02,1],[]); %[output:47e293ac]
w111_cuts(2) = w2e400GPoff200 - replicate(bg_400o02,w2e400GPoff200); plot(w111_cuts(2)); lz 0 0.5;keep_figure;w111_cuts(2)  = cut(w111_cuts(2) ,[0,0.02,1],[]); %[output:5506b683]


hc.log_level = ll;

%%
if ~exist('magi','var')
    magi = MagneticIons();
end
hc.log_level = -2;

disp('*************************************************') %[output:6dcc5485]
disp('****  MAG_FF CORRECTED DATA  ********************') %[output:0df78620]
disp('*************************************************') %[output:9abc2004]

w111_cc = repmat(sqw,1,numel(w111_cuts)) %[output:8ab204c4]
for i=1:numel(w111_cuts) %[output:group:3b4f1ce7]
    w111_cc(i) = magi.correct_mag_ff(w111_cuts(i));
    plot(w111_cc(i)); lz 0 2;keep_figure;drawnow     %[output:6756b9bc] %[output:7a83f92f]
end %[output:group:3b4f1ce7]

hc.log_level = ll;


%%
sources = num2cell(w111_cc);
src_proj = arrayfun(@(x)x.data.proj,w111_cc);
targ_proj = w111_sym(1).data.proj;
targ_proj.offset = [0,0,0];
w2_400Sum = sqw_op_bin_pixels(sources,@move_all_to_proj,{src_proj}, ...
    targ_proj,[0,0.005,0.5],[-0.1,0.1],[-0.1,0.1],[0,4,450], ...
    '-combine');
w2_400Sum.full_filename = [fname,',  ei400_allSym; bg_removed; ff_corrected'];

plot(w2_400Sum); lz 0 1;keep_figure; %[output:8d578811]
%%
ff = gcf;
savefig(ff,'sGP_Ei400_allSym_bg_rem_ff_corr');

